mod listing;
mod consent;
mod tokens;
mod binding;
use crate::{auth,common::*,catalog};
use rusqlite::params;
use serde_json::{Value,json};

pub(super) type CommerceResult<T>=std::result::Result<T,CommerceError>;
#[derive(Debug)]
pub(super) struct CommerceError{code:&'static str,description:String,status:u16,commit:bool}
impl CommerceError{fn new(code:&'static str,msg:impl Into<String>,status:u16)->Self{Self{code,description:msg.into(),status,commit:false}}}
impl From<ApiError> for CommerceError{fn from(e:ApiError)->Self{Self::new(if e.status==401||e.status==403{"access_denied"}else{"invalid_request"},e.message,e.status)}}
impl From<rusqlite::Error> for CommerceError{fn from(e:rusqlite::Error)->Self{ApiError::from(e).into()}}
impl From<serde_json::Error> for CommerceError{fn from(e:serde_json::Error)->Self{ApiError::from(e).into()}}
fn error(code:&'static str,msg:impl Into<String>,status:u16)->CommerceError{CommerceError::new(code,msg,status)}
fn browser(ctx:&Context,fresh:bool)->CommerceResult<Value>{if !ctx.header("authorization").is_empty(){return Err(error("access_denied","请在商家浏览器中管理此授权",401));}let s=auth::session(ctx,&["admin"],None)?;if fresh{auth::require_recent(&s)?;}Ok(s)}
fn management(ctx:&Context,fresh:bool)->CommerceResult<Value>{let s=auth::session(ctx,&["admin"],None)?;if fresh{auth::require_recent(&s)?;}Ok(s)}
fn client(ctx:&Context,cid:&str,active:bool)->CommerceResult<Value>{let c=row(&ctx.conn,"SELECT c.* FROM commerce_clients c JOIN shops s ON s.id=c.shop_id WHERE c.id=? AND s.enabled=1",[cid])?.ok_or_else(||error("invalid_client","商城应用无效或已撤销",401))?;if active&&flag(&c,"revoked"){return Err(error("invalid_client","商城应用已撤销",401));}Ok(c)}
fn grant(ctx:&Context,gid:&str,active:bool)->CommerceResult<Value>{let g=row(&ctx.conn,"SELECT g.* FROM commerce_grants g JOIN shops s ON s.id=g.shop_id WHERE g.id=? AND s.enabled=1",[gid])?.ok_or_else(||error("invalid_token","商城授权无效",401))?;if active&&(flag(&g,"revoked")||number(&g,"expires")<=now()){return Err(error("invalid_token","商城授权已过期或撤销",401));}client(ctx,text(&g,"client_id"),active)?;Ok(g)}
fn client_view(value:&Value)->Value{let mut v=json_field(value,"metadata",json!({}));for k in ["id","shop_id"]{v[k]=value[k].clone();}v["client_id"]=value["id"].clone();v["created_at"]=value["created"].clone();v["client_id_issued_at"]=json!(number(value,"created")as i64);v["enabled"]=json!(!flag(value,"revoked"));v}
fn owned_client(ctx:&Context,s:&Value,cid:&str,active:bool)->CommerceResult<Value>{let c=client(ctx,cid,active)?;let selected=catalog::selected_shop(ctx,s,if ctx.q("shop_id").is_empty(){text(&c,"shop_id")}else{ctx.q("shop_id")})?;if selected!=text(&c,"shop_id"){return Err(error("access_denied","没有此商城应用的管理权限",403));}Ok(c)}
fn revoke(ctx:&Context,gid:&str,actor:&str,action:&str)->CommerceResult<()>{let g=grant(ctx,gid,false)?;ctx.conn.execute("UPDATE commerce_grants SET revoked=1 WHERE id=?",[gid])?;ctx.conn.execute("DELETE FROM commerce_tokens WHERE grant_id=? AND kind='access'",[gid])?;ctx.conn.execute("UPDATE commerce_issuances SET response_ciphertext=NULL WHERE grant_id=?",[gid])?;audit(&ctx.conn,actor,action,gid,Some(text(&g,"shop_id")))?;Ok(())}
fn machine(ctx:&Context,bearer:bool)->CommerceResult<String>{if !ctx.cookie("extore_session").is_empty(){return Err(error("invalid_request","商城接口不能混用浏览器登录凭证",401));}let h=ctx.header("authorization");if bearer{let p=h.split_whitespace().collect::<Vec<_>>();if p.len()!=2||!p[0].eq_ignore_ascii_case("bearer")||p[1].len()!=43||!p[1].bytes().all(|b|b.is_ascii_alphanumeric()||b==b'_'||b==b'-'){return Err(error("invalid_token","请提供有效商城访问令牌",401));}Ok(p[1].to_owned())}else if !h.is_empty(){Err(error("invalid_client","公共客户端仅支持 PKCE 认证",401))}else{Ok(String::new())}}
fn access(ctx:&Context,scope:&str)->CommerceResult<Value>{let raw=machine(ctx,true)?;let stored=row(&ctx.conn,"SELECT grant_id FROM commerce_tokens WHERE digest=? AND kind='access' AND expires>?",params![digest(&raw),now()])?.ok_or_else(||error("invalid_token","商城访问令牌无效或已到期",401))?;let g=grant(ctx,text(&stored,"grant_id"),true)?;if !json_field(&g,"scopes",json!([])).as_array().unwrap().contains(&json!(scope)){return Err(error("insufficient_scope","商城授权未允许此操作",403));}ctx.conn.execute("UPDATE commerce_grants SET last_used=? WHERE id=?",params![now(),text(&g,"id")])?;Ok(g)}
fn allowed_product(ctx:&Context,g:&Value,pid:&str)->CommerceResult<Value>{if !json_field(g,"product_ids",json!([])).as_array().unwrap().contains(&json!(pid)){return Err(error("access_denied","商品不在批准范围",403));}let p=catalog::require_active(ctx,pid)?;if text(&p,"shop_id")!=text(g,"shop_id"){return Err(error("product_unavailable","商品不属于当前店铺",409));}Ok(p)}
fn grant_view(ctx:&Context,g:&Value)->CommerceResult<Value>{let c=client(ctx,text(g,"client_id"),false)?;let pids=json_field(g,"product_ids",json!([]));let mut products=Vec::new();for p in pids.as_array().unwrap(){let pid=p.as_str().unwrap_or("");let name=row(&ctx.conn,"SELECT json_extract(config,'$.name') AS name FROM products WHERE id=?",[pid])?.map(|v|v["name"].clone()).unwrap_or(json!(pid));products.push(json!({"id":pid,"name":name}));}let mut limits=json_field(g,"card_limits",json!([]));for l in limits.as_array_mut().unwrap(){l["remaining"]=json!(integer(l,"max_count",0)-integer(l,"issued_count",0));}Ok(json!({"id":g["id"],"client_id":g["client_id"],"client_name":json_field(&c,"metadata",json!({}))["client_name"],"shop_id":g["shop_id"],"scopes":json_field(g,"scopes",json!([])),"product_ids":pids,"products":products,"card_limits":limits,"expires":g["expires"],"created_at":g["created"],"revoked":flag(g,"revoked"),"last_used":g["last_used"]}))}

pub fn handle(ctx:&mut Context)->Result<Option<Reply>>{
    if !(ctx.path.starts_with("/api/integrations/commerce/")||ctx.path.starts_with("/api/admin/commerce/")||ctx.path=="/oauth/authorize"||ctx.path=="/.well-known/oauth-authorization-server"){return Ok(None);}
    ctx.conn.execute_batch("SAVEPOINT commerce_request")?;
    match route(ctx){Ok(result)=>{ctx.conn.execute_batch("RELEASE commerce_request")?;Ok(result)},Err(e)=>{if e.commit{ctx.conn.execute_batch("RELEASE commerce_request")?;}else{ctx.conn.execute_batch("ROLLBACK TO commerce_request; RELEASE commerce_request")?;}let mut r=Reply::json(json!({"error":e.code,"error_description":e.description,"detail":e.description}));r.status=e.status;if matches!(e.code,"invalid_token"|"insufficient_scope"){r.headers.insert("www-authenticate",axum::http::HeaderValue::from_str(&format!("Bearer error=\"{}\"",e.code)).unwrap());}Ok(Some(r))}}
}
fn route(ctx:&mut Context)->CommerceResult<Option<Reply>>{
    if ctx.is("GET","/.well-known/oauth-authorization-server"){return Ok(Some(Reply::json(listing::metadata(ctx))));}
    if ctx.is("GET","/api/integrations/commerce/schema"){return Ok(Some(Reply::json(serde_json::from_str(include_str!("../docs/schemas/commerce-import.v1.schema.json"))?)));}
    if let Some(r)=consent::handle(ctx)?{return Ok(Some(r));}
    if let Some(r)=tokens::handle(ctx)?{return Ok(Some(r));}
    if let Some(r)=binding::handle(ctx)?{return Ok(Some(r));}
    if ctx.is("GET","/api/admin/commerce/clients"){let s=management(ctx,false)?;let own=catalog::selected_shop(ctx,&s,ctx.q("shop_id"))?;let items=rows(&ctx.conn,"SELECT * FROM commerce_clients WHERE shop_id=? AND (?='all' OR revoked=0) ORDER BY created DESC LIMIT 200",params![own,ctx.q("view")])?.iter().map(client_view).collect::<Vec<_>>();return Ok(Some(Reply::json(json!({"clients":items}))));}
    if ctx.is("POST","/api/admin/commerce/clients"){
        let s=management(ctx,true)?;let own=catalog::selected_shop(ctx,&s,ctx.q("shop_id"))?;let name=ctx.b("client_name").trim();if name.is_empty()||name.chars().count()>100||name.chars().any(char::is_control){return Err(error("invalid_request","商城名称无效",400));}
        let redirects=ctx.body["redirect_uris"].as_array().ok_or_else(||error("invalid_request","请设置回调地址",400))?;if redirects.is_empty()||redirects.len()>5{return Err(error("invalid_request","最多登记 5 个回调地址",400));}let mut unique=std::collections::BTreeSet::new();for value in redirects{let uri=value.as_str().ok_or_else(||error("invalid_request","回调地址无效",400))?;consent::validate_redirect(uri)?;if !unique.insert(uri){return Err(error("invalid_request","回调地址不能重复",400));}}
        let count=ctx.conn.query_row("SELECT COUNT(*) FROM commerce_clients WHERE shop_id=? AND revoked=0",[&own],|r|r.get::<_,i64>(0))?;if count>=50{return Err(error("invalid_request","商城应用数量已达上限",409));}
        let metadata=json!({"client_name":name,"redirect_uris":redirects,"token_endpoint_auth_method":"none","grant_types":["authorization_code","refresh_token"],"response_types":["code"]});let cid=id();ctx.conn.execute("INSERT INTO commerce_clients(id,shop_id,metadata,created) VALUES (?,?,?,?)",params![cid,own,listing::canonical_ascii(&metadata),now()])?;audit(&ctx.conn,&actor(&s),"commerce.client.create",&cid,Some(&own))?;return Ok(Some(Reply::json(client_view(&client(ctx,&cid,true)?))));
    }
    if ctx.path.starts_with("/api/admin/commerce/clients/")&&ctx.method==axum::http::Method::DELETE{let s=management(ctx,true)?;let cid=ctx.path.rsplit('/').next().unwrap();owned_client(ctx,&s,cid,false)?;for g in rows(&ctx.conn,"SELECT id FROM commerce_grants WHERE client_id=? AND revoked=0",[cid])?{revoke(ctx,text(&g,"id"),&actor(&s),"commerce.grant.revoke")?;}ctx.conn.execute("UPDATE commerce_clients SET revoked=1 WHERE id=?",[cid])?;ctx.conn.execute("UPDATE commerce_requests SET status='denied' WHERE client_id=? AND status='pending'",[cid])?;return Ok(Some(Reply::json(json!({"ok":true}))));}
    if ctx.is("GET","/api/admin/commerce/grants"){let s=management(ctx,false)?;let own=catalog::selected_shop(ctx,&s,ctx.q("shop_id"))?;let mut values=Vec::new();for g in rows(&ctx.conn,"SELECT * FROM commerce_grants WHERE shop_id=? AND (?='all' OR (revoked=0 AND expires>?)) ORDER BY created DESC LIMIT 200",params![own,ctx.q("view"),now()])?{values.push(grant_view(ctx,&g)?);}return Ok(Some(Reply::json(json!({"grants":values}))));}
    if ctx.path.starts_with("/api/admin/commerce/grants/")&&ctx.method==axum::http::Method::DELETE{let s=management(ctx,true)?;let gid=ctx.path.rsplit('/').next().unwrap();let g=grant(ctx,gid,false)?;catalog::selected_shop(ctx,&s,text(&g,"shop_id"))?;revoke(ctx,gid,&actor(&s),"commerce.grant.revoke")?;return Ok(Some(Reply::json(json!({"ok":true}))));}
    if ctx.path.starts_with("/api/integrations/commerce/products")&&ctx.method==axum::http::Method::GET{let g=access(ctx,"products.read")?;let mp=json_field(&g,"scopes",json!([])).as_array().unwrap().contains(&json!("marketplace.sync"));if let Some(pid)=ctx.path.strip_prefix("/api/integrations/commerce/products/"){allowed_product(ctx,&g,pid)?;return Ok(Some(Reply::json(listing::listing(ctx,pid,mp)?)));}let mut values=Vec::new();for pid in json_field(&g,"product_ids",json!([])).as_array().unwrap(){let pid=pid.as_str().unwrap_or("");let p=catalog::product(ctx,pid)?;if flag(&p,"deleted"){continue;}allowed_product(ctx,&g,pid)?;values.push(listing::listing(ctx,pid,mp)?);}let shop=required(&ctx.conn,"SELECT id,name FROM shops WHERE id=?",[text(&g,"shop_id")],"店铺不存在")?;return Ok(Some(Reply::json(json!({"schema":"extore.commerce-catalog.v1","issuer":ctx.app.origin,"shop":shop,"grant_id":g["id"],"products":values}))));}
    Ok(None)
}
